function sanitize(text) {
  if (!text) return '';

  return String(text)
    // escape backslashes
    .replace(/\\/g, '\\\\')
    // escape quotes
    .replace(/"/g, '\\"')
    // remove carriage returns
    .replace(/\r/g, '')
    // replace newlines with Slack-safe line breaks
    .replace(/\n/g, '\\n')
    // remove other control characters
    .replace(/[\u0000-\u001F\u007F]/g, '');
}

return $input.all().map(item => {
  const tweetText = sanitize(item.json.tweet_text);
  const reason = sanitize(item.json.reason);
  const authorName = sanitize(item.json.author_name);
  const authorUsername = sanitize(item.json.author_username);

  return {
    json: {
      tweet_id: item.json.tweet_id,
      tweet_text: tweetText,
      author_name: authorName,
      author_username: authorUsername,
      created_at: item.json.created_at,
      reason: reason,
      tweet_url: item.json.tweet_url
    }
  };
});

// Get OpenAI HTTP response safely
const response = $input.first().json;

// Guard: no valid response
if (
  !response ||
  !response.choices ||
  !response.choices[0] ||
  !response.choices[0].message ||
  !response.choices[0].message.content
) {
  console.log('No valid response received');
  return [];
}

// Raw AI output (string)
const rawContent = response.choices[0].message.content;
console.log('Raw AI Content:', rawContent);

// Parse JSON safely
let parsed;
try {
  parsed = JSON.parse(rawContent);
  console.log('Successfully parsed JSON');
} catch (e) {
  console.log('JSON Parse Error:', e.message);
  return [];
}

// Ensure array exists
const negativeTweets = Array.isArray(parsed.negative_tweets)
  ? parsed.negative_tweets
  : [];

console.log('Total negative tweets found:', negativeTweets.length);

// Return each negative tweet as a separate n8n item
return negativeTweets.map((tweet, index) => {
  // Create X (Twitter) URL
  const tweetUrl = `https://x.com/${tweet.author_username}/status/${tweet.tweet_id}`;

  console.log(`\nTweet #${index + 1}:`);
  console.log('  ID:', tweet.tweet_id);
  console.log('  Text:', tweet.tweet_text);
  console.log('  Author:', tweet.author_name, `(@${tweet.author_username})`);
  console.log('  Created:', tweet.created_at);
  console.log('  Reason:', tweet.reason);
  console.log('  URL:', tweetUrl);

  return {
    json: {
      tweet_id: tweet.tweet_id,
      tweet_text: tweet.tweet_text,
      author_username: tweet.author_username,
      author_name: tweet.author_name,
      created_at: tweet.created_at,
      reason: tweet.reason,
      tweet_url: tweetUrl
    }
  };
});

// Get combined tweets array
const items = $input.all();

if (!items.length || !items[0].json.data) {
  return [{
    json: {
      tweets_for_ai: "[]"
    }
  }];
}

// Flatten tweets
const tweets = items[0].json.data;

// Keep only fields needed for sentiment analysis
const cleanedTweets = tweets.map(t => ({
  id: t.id,
  text: t.text,
  author_username: t.author_username,
  author_name: t.author_name,
  created_at: t.created_at,
  metrics: t.public_metrics
}));

// OPTIONAL SAFETY: limit tweets per request (important for OpenAI)
const MAX_TWEETS = 30;
const limitedTweets = cleanedTweets.slice(0, MAX_TWEETS);

// Stringify for OpenAI
return [{
  json: {
    tweets_for_ai: JSON.stringify(limitedTweets)
  }
}];

// Combine all pages of tweets
const allItems = $input.all();

if (!allItems || allItems.length === 0) {
  console.log('No items to combine');
  return [];
}

let allTweets = [];

// Collect tweets from all pages
for (const item of allItems) {
  if (item.json.tweets && Array.isArray(item.json.tweets)) {
    allTweets = allTweets.concat(item.json.tweets);
  }
}

if (allTweets.length === 0) {
  console.log('No tweets found in any page');
  return [];
}

// Remove duplicates by tweet ID
const uniqueTweets = [];
const seenIds = new Set();

for (const tweet of allTweets) {
  if (tweet.id && !seenIds.has(tweet.id)) {
    seenIds.add(tweet.id);
    uniqueTweets.push(tweet);
  }
}

// Sort by ID (newest first)
uniqueTweets.sort((a, b) => {
  const aId = BigInt(a.id);
  const bId = BigInt(b.id);
  return aId > bId ? -1 : 1;
});

console.log(`Combined ${uniqueTweets.length} unique tweets from ${allItems.length} pages`);

// âœ… Return everything inside a single `data` field
return [
  {
    json: {
      data: uniqueTweets
    }
  }
];

// Parse Twitter API response
const response = $input.item.json;

// Check if we got an error
if (response.error || response.errors) {
  console.log('Twitter API error:', response);
  return [];
}

const tweets = response.data || [];
const users = response.includes?.users || [];
const nextToken = response.meta?.next_token || null;

// If no tweets, return empty
if (tweets.length === 0) {
  console.log('No new tweets found');
  return [];
}

// Map tweets to include author username
const tweetsWithAuthors = tweets.map(tweet => {
  const author = users.find(u => u.id === tweet.author_id);
  return {
    id: tweet.id,
    text: tweet.text,
    created_at: tweet.created_at,
    author_id: tweet.author_id,
    author_username: author?.username || 'unknown',
    author_name: author?.name || 'Unknown',
    author_verified: author?.verified || false,
    public_metrics: tweet.public_metrics
  };
});

console.log(`Found ${tweetsWithAuthors.length} tweets`);

return [{
  json: {
    tweets: tweetsWithAuthors,
    next_token: nextToken,
    result_count: tweets.length,
    has_more: !!nextToken
  }
}];
